async function loadQuestionImage(){const q=currentQ(),img=$('#q-image'),loading=$('#image-loading');try{if(q.pack&&!(window.PYQ_IMAGES?.[q.assetId||q.id]||window.SOM_IMAGES?.[q.assetId||q.id])){if(!imagePacks[q.pack])imagePacks[q.pack]=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=q.pack;script.onload=resolve;script.onerror=()=>{delete imagePacks[q.pack];reject(Error('Image bundle failed to load'))};document.head.append(script)});await imagePacks[q.pack]}if(!img.isConnected)return;img.src=window.PYQ_IMAGES?.[q.assetId||q.id]||window.SOM_IMAGES?.[q.assetId||q.id]||q.imageUrl||'public/'+q.image;img.onload=()=>{img.hidden=false;loading.hidden=true};img.onerror=()=>{loading.textContent='Could not load this screenshot. Reopen the app or check that all asset packs are present.'};if(img.complete&&img.naturalWidth){img.hidden=false;loading.hidden=true}}catch{loading.textContent='Could not load screenshot. Please reload the workspace.'}}
