function mockView(){return `${header('Train under exam conditions.','Build subject or mixed-subject timed sets from your available question banks.','EXAM SIMULATOR')}<div class="lower-grid"><section class="panel"><h2>Design your session</h2><p class="muted" style="font-size:11px;margin:10px 0 25px">A custom practice set. It does not claim to reproduce a complete official paper.</p><form id="mock-form"><fieldset class="test-subjects"><legend>Subjects to include</legend>${PYQCatalog.subjects.filter(s=>BANK.some(q=>q.subject===s.id)).map(s=>`<label><input type="checkbox" name="subjects" value="${s.id}" ${state.subject==='all'||state.subject===s.id?'checked':''}> ${esc(s.name)}</label>`).join('')}<small>Newly integrated subjects appear here automatically.</small></fieldset><div class="form-grid"><label class="field">Exam track<select name="exam">${Object.entries(TRACKS).map(([id,t])=>`<option value="${id}">${t.name}</option>`).join('')}</select></label><label class="field">Answer format<select name="type"><option value="all">All available formats</option><option>MCQ</option><option>MSQ</option><option>NAT</option><option>TEXT</option><option>WRITTEN</option></select></label><label class="field">Number of questions<input name="count" type="number" min="1" max="200" value="20" required></label><label class="field">Time limit (minutes)<input name="minutes" type="number" min="1" max="300" value="30" required></label><label class="field">Selection<select name="selection"><option value="adaptive">Adaptive: mistakes, flags, then new</option><option value="random">Randomised mix</option><option value="weak">Mistakes first</option><option value="new">Unpractised first</option></select></label><label class="field">Grading coverage<select name="coverage"><option value="key">Only questions with keys</option><option value="all">Include questions awaiting keys</option></select></label></div><div class="form-actions"><button class="primary" type="submit">Enter exam mode ↗</button><span class="muted" style="font-size:10px">Auto-submits when time ends.</span></div></form></section><section class="panel"><h3>Know the rules</h3><div class="coverage" style="margin-top:20px"><p><strong>GATE MCQ</strong><br>One correct option. Wrong answers lose one third of the question’s marks.</p><br><p><strong>GATE MSQ / NAT</strong><br>MSQ requires the exact option set. NAT is checked against the accepted range. No negative or partial marks.</p><br><p><strong>ESE Prelims</strong><br>Single-choice questions, with one third negative marking. No calculator in this track.</p><br><p><strong>Mains</strong><br>Conventional written practice with a separate self-assessed rubric. No automatic correctness claims.</p></div><div class="callout">Answers and keys remain hidden during a test. The timer continues if you leave or reload the page.</div></section></div>`}
function resultsView(){const s=state.session;if(!s)return insightHome();const qs=s.ids.map(qData),t=C.totals(qs,s.answers);return `${header('A session closer to mastery.','Use the result to decide what deserves another attempt.','SESSION REVIEW')}<div class="results-grid">${stat('Automatically graded score',t.max?`${t.score.toFixed(2)} <small>/ ${t.max}</small>`:'—','Only questions with usable keys included')}${stat('Correct answers',`${t.correct} <small>/ ${t.correct+t.wrong}</small>`,`${t.wrong} incorrect · ${t.skipped} skipped`)}${stat('Awaiting review',t.ungraded+t.manual,`${t.ungraded} source issues / ungraded · ${t.manual} written responses`)}</div><div class="section-head"><h2>Question-by-question review</h2><button class="primary" data-action="retry-mistakes">Retry incorrect questions ↗</button></div><div class="question-card"><table class="bank-table"><thead><tr><th>QUESTION</th><th>YOUR ANSWER</th><th>RESULT</th><th>ACCEPTED ANSWER</th><th></th></tr></thead><tbody>${qs.map(q=>{const g=C.grade(q,s.answers[q.id]);return `<tr><td>${esc(q.title)}${q.occurrences.length>1?`<span class="library-count-badge">${q.occurrences.length} appearances</span>`:''}<small>${esc(subjectName(q.subject))} · ${esc(q.chapter)}</small></td><td>${esc(Array.isArray(s.answers[q.id])?s.answers[q.id].join(', '):String(s.answers[q.id]??'—').slice(0,60))}</td><td>${g.status}<small>${g.score===null?(state.attempts.filter(a=>a.id===q.id&&a.session===s.start).at(-1)?.selfScore!==undefined?'Self-assessed: '+state.attempts.filter(a=>a.id===q.id&&a.session===s.start).at(-1).selfScore.toFixed(1)+' / '+state.attempts.filter(a=>a.id===q.id&&a.session===s.start).at(-1).selfMax:'Not auto-graded'):g.score.toFixed(2)+' marks'}</small></td><td>${q.key?esc(keyLabel(q)):q.answerIssue?'Source issue':'Model reference'}</td><td><button data-result-answer="${esc(q.id)}">View answer</button><button data-open="${q.id}">Revisit</button></td></tr>`}).join('')}</tbody></table></div>`}
function reviewView(){return learningRevision()}
function analytics(){const at=autoAttempts(),correct=at.filter(a=>a.status==='correct').length,chapters=[...new Set(at.map(a=>byId.has(a.id)?subjectName(byId.get(a.id).subject)+' · '+byId.get(a.id).chapter:null))].filter(Boolean).map(ch=>{const a=at.filter(a=>subjectName(byId.get(a.id)?.subject)+' · '+byId.get(a.id)?.chapter===ch);return {ch,n:a.length,c:a.filter(x=>x.status==='correct').length}}).sort((a,b)=>a.c/a.n-b.c/b.n);return `${header('See what is getting stronger.','Honest feedback from your submitted practice. No predicted ranks or invented benchmarks.','PERFORMANCE')}${subjectAnalytics()}<div class="stats">${stat('Total submissions',scopeAttempts().length,'Includes ungraded and written responses')}${stat('Graded accuracy',at.length?Math.round(correct/at.length*100)+'<small>%</small>':'—','Correct / correct + incorrect')}${stat('Unique questions',tracked().size,`${scopeBank().length} questions in the library`)}${stat('Net graded marks',at.reduce((n,a)=>n+(a.score||0),0).toFixed(2),'Including negative marks')}</div><div class="lower-grid"><section class="panel"><h3>Chapter accuracy · weakest first</h3>${chapters.length?`<div class="bar-chart">${chapters.map(c=>`<div class="bar-row"><span>${esc(c.ch)}<small class="muted" style="display:block">${c.n} attempts</small></span><div class="bar-track"><i style="width:${c.c/c.n*100}%"></i></div><span>${Math.round(c.c/c.n*100)}%</span></div>`).join('')}</div>`:'<div class="empty">Submit a few graded questions to reveal your chapter strengths.</div>'}</section><section class="panel"><h3>Recent activity</h3>${scopeAttempts().length?scopeAttempts().slice(-12).reverse().map(a=>`<div class="history-row"><div>${esc(TRACKS[byId.get(a.id)?.exam]?.short||a.id)} · ${esc(byId.get(a.id)?.number)}<small>${new Date(a.at).toLocaleDateString('en-IN')} · ${a.seconds||0}s · ${a.status}</small></div><span>${a.selfScore!==undefined?'Self: '+a.selfScore.toFixed(1)+' / '+a.selfMax:a.score===null?'—':a.score.toFixed(2)}</span></div>`).join(''):'<div class="empty">Your practice history will appear here.</div>'}</section></div>`}
function sourceReconciliationPanel(){const r=window.PYQ_SOURCE_RECONCILIATION;if(!r)return '';return `<section class="panel source-reconciliation"><div class="section-head"><div><div class="eyebrow">SOURCE RECONCILIATION · ${esc(r.date)}</div><h2>Know exactly what is covered.</h2><p>Printed question numbering is checked before duplicate consolidation.</p></div></div><div class="table-wrap"><table><thead><tr><th>Source section</th><th>Numbered items covered</th><th>Status</th></tr></thead><tbody>${r.sections.map(s=>`<tr><td>${esc(s.name)}<small>PDF pages ${esc(s.pages)}</small></td><td>${num(s.represented)} / ${num(s.expected)}</td><td>${esc(s.status)}</td></tr>`).join('')}</tbody></table></div>${r.blocked.map(b=>`<div class="source-gap"><strong>${b.numbers.length} questions need a readable source scan</strong><p>${esc(b.source)} · ${esc(b.chapter)} · Q7.16–7.41</p><p>${esc(b.reason)}</p></div>`).join('')}<p class="chart-note">Thermodynamics now includes the complete numbered supplied book sections, GATE ME/XE papers through 2026, older and recent ESE Prelims, and ESE/CSE Mains 2017–2026. Coverage and source issues are recorded in thermo-source-audit.json. Mains answers are independently worked self-review references, not official marking schemes. Repeated appearances stay in source references and count once in practice. Printed-book keys are labelled separately from official keys and independently derived answers.</p></section>`}
function dataSettings(){const qs=BANK.map(q=>qData(q.id)),n=qs.filter(q=>q.key).length;return `${header('Your workspace. Your data.','Keep a backup, review your sources, and understand what is ready to grade.','DATA & SETTINGS')}<section class="panel"><div class="settings-row"><div><h3>Export progress</h3><p>Download answers, attempts, notes, flags, personal keys, sketches, study plans and settings as a JSON backup.</p></div><button class="primary" data-action="export">Export backup ↓</button></div><div class="settings-row"><div><h3>Restore a backup</h3><p>Import a PYQ Nexus backup or an existing SOM Lab backup. You will review the import before replacing progress.</p></div><button data-action="import">Import backup ↑</button><input id="backup-file" type="file" accept="application/json,.json" hidden></div><div class="settings-row"><div><h3>Appearance</h3><p>Choose a comfortable workspace for long study sessions.</p></div><button data-action="theme">Use ${state.theme==='dark'?'light':'dark'} theme</button></div><div class="settings-row"><div><h3>Grading coverage</h3><p>${n} objective questions have answer keys. ${qs.filter(q=>q.answerIssue).length} source issues are explained and excluded from automatic scoring. ${qs.filter(q=>q.type==='WRITTEN').length} written questions have model references and a self-review rubric.</p></div><button data-action="issues">Review source issues</button></div><div class="settings-row"><div><h3>Refresh saved grades</h3><p>Apply the current answer keys to past objective responses. Preview changes first; original grades stay in your backup history.</p></div><button data-action="recheck-answers">Recheck saved answers</button></div><div class="settings-row"><div><h3>Question bank provenance</h3><p>Strength of Materials and Fluid Mechanics use the supplied screenshot compilations. Official UPSC Mains PDFs supply the new Heat Transfer written questions. Each subject lists its source documents and answer-key coverage below. Scanned books provide supplementary material or matching reference keys where identified. CSE Mains is supplementary and is never labelled ESE. OCR search text may contain recognition errors; use the original screenshot as the question.</p></div></div><div class="coverage" style="margin-top:20px">${[{subject:'som',sources:window.SOM_SOURCES||[]},...(window.PYQ_SOURCES||[])].map(group=>`<h3>${esc(subjectName(group.subject))}</h3><br>${group.sources.map(source=>`<p><strong>${esc(source.file)}</strong><br>${source.questions!==undefined?num(source.questions+(window.PYQ_ANSWER_DATA.additional||[]).filter(q=>q.subject===group.subject&&q.source===source.file).length)+' source entries':esc(source.status)}${source.note?'<br>'+esc(source.note):''}</p><br>`).join('')}`).join('')}<p>Marking rules: <a href="https://gate2026.iitg.ac.in/QPs-answer-keys.html" target="_blank" rel="noopener">Official GATE rules ↗</a> · <a href="https://upsc.gov.in/sites/default/files/Notif-ESEP-25-Engl-18092024.pdf" target="_blank" rel="noopener">UPSC ESE examination scheme ↗</a></p><p>The website is hosted on GitHub Pages. Your study data stays on this device. Progress is stored in this browser, not synchronised to GitHub. Exam mode is a practice simulation, not an official examination interface.</p></div></section>${sourceReconciliationPanel()}`}
function showModal(title,body){$('#modal-body').innerHTML=`<div class="modal-head"><h2>${title}</h2><button data-close aria-label="Close dialog">×</button></div>${body}`;modal.showModal()}
function editKey(){const q=currentQ();if(state.session.mode==='exam'){toast('Key editing is unavailable during a test.');return}showModal('Review question metadata',`<p>Personal changes stay on this device and are labelled personal keys. Consult the original paper or a trusted solution before adding a key.</p><form id="key-form"><label class="field">Question type<select name="type">${['MCQ','MSQ','NAT','TEXT','WRITTEN'].map(t=>`<option ${q.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Maximum marks<input type="number" name="marks" min="1" max="100" value="${q.marks||2}" required></label><label class="field">Accepted options / NAT lower bound / short-answer variants separated by |<input name="answer" value="${esc(q.type==='NAT'?q.key?.min??'':q.type==='TEXT'?q.key?.acceptedText?.join('|')||'':q.key?.options?.join(',')||'')}" placeholder="Leave blank to keep grading pending"></label><label class="field">NAT upper bound<input name="upper" value="${q.key?.max??''}" placeholder="For numerical answers only"></label><label class="field">Key source / explanation<input name="source" value="${esc(q.keySource||'')}" placeholder="Reference or your verification note"></label><div class="form-actions"><button type="submit" class="primary">Save personal metadata</button></div></form>`);$('#key-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),type=f.get('type'),marks=Number(f.get('marks')),answer=f.get('answer').trim();let key=null;if(type==='NAT'&&answer){const min=Number(answer),max=Number(f.get('upper'));if(!f.get('upper').trim()||!Number.isFinite(min)||!Number.isFinite(max)||min>max){toast('Enter a valid lower and upper bound.');return}key={min,max}}else if(type==='TEXT'&&answer){const acceptedText=answer.split('|').map(v=>v.trim()).filter(Boolean);if(!acceptedText.length){toast('Enter at least one short-answer reference.');return}key={acceptedText}}else if(['MCQ','MSQ'].includes(type)&&answer){const options=[...new Set(answer.toUpperCase().split(/[,;\s]+/).filter(Boolean))];if(!options.every(x=>['A','B','C','D'].includes(x))||type==='MCQ'&&options.length!==1){toast('Use A–D; MCQ needs exactly one option.');return}key={options}}state.overrides[q.id]={type,marks,key,keyStatus:key?'user':'missing',keySource:f.get('source')||'Personal key'};delete state.session.answers[q.id];delete state.session.submitted[q.id];revealed.delete(q.id);save();modal.close();render();toast('Personal metadata saved')};}
function calculator(){showModal('Scientific calculator',`<p>Degree mode · supports brackets, powers, sqrt, sin, cos, tan, log, ln and pi.</p><input id="calc-input" class="calc-display" aria-label="Calculator expression" placeholder="e.g. 200000*pi*20^2/4"><div id="calc-output" class="calc-output" aria-live="polite"></div><div class="calc-grid">${['sin(','cos(','tan(','sqrt(','C','7','8','9','/','(', '4','5','6','*',')','1','2','3','-','^','0','.','pi','+','='].map(k=>`<button data-calc="${k}" class="${k==='='?'primary':''}">${k}</button>`).join('')}</div>`);$('#calc-input').onkeydown=e=>{if(e.key==='Enter')calcResult()}}
function calcResult(){try{$('#calc-output').textContent=C.calc($('#calc-input').value)}catch(e){$('#calc-output').textContent=e.message}}
function scratch(){const id=currentQ().id;showModal('Working sketchpad',`<p>Use a mouse, stylus or touch. Your drawing stays with this question.</p><canvas class="scratch" id="scratch" width="900" height="560" aria-label="Drawing canvas"></canvas><div class="form-actions"><button id="clear-sketch">Clear canvas</button><button id="save-sketch" class="primary">Save drawing</button></div>`);const canvas=$('#scratch'),ctx=canvas.getContext('2d');ctx.strokeStyle='#233124';ctx.lineWidth=3;ctx.lineCap='round';if(state.drawings[id]){const image=new Image;image.onload=()=>ctx.drawImage(image,0,0);image.src=state.drawings[id]}let draw=false;function point(e){const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height]}canvas.onpointerdown=e=>{draw=true;canvas.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e))};canvas.onpointermove=e=>{if(draw){ctx.lineTo(...point(e));ctx.stroke()}};canvas.onpointerup=()=>draw=false;$('#clear-sketch').onclick=()=>ctx.clearRect(0,0,canvas.width,canvas.height);$('#save-sketch').onclick=()=>{state.drawings[id]=canvas.toDataURL();save();modal.close();toast('Sketch saved')}}
function selfReview(questionId=null){const q=questionId?qData(questionId):currentQ();const attempt=state.attempts.filter(a=>a.id===q.id&&(!state.session?.ids.includes(q.id)||a.session===state.session.start)).at(-1);if(!attempt){toast('Save your written response before recording a self-assessed score.');return}showModal('Mains self-review',`<p>Compare your response with the model reference, then assess method, working, result and presentation. This is a self-assessment, not an official or automatic grade.</p>${answerReference(q)}<form id="rubric-form"><div class="rubric">${[['method','Method & assumptions'],['working','Derivation & working'],['answer','Result & units'],['clarity','Diagram & presentation']].map(([id,t])=>`<label>${t} (0–5)<input name="${id}" type="number" min="0" max="5" step=".5" value="0" required></label>`).join('')}</div><label class="field">Maximum marks<input name="max" type="number" min="1" max="100" value="${q.marks||10}" required></label><button class="primary" type="submit">Save self-assessed score</button></form>`);$('#rubric-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),ratio=['method','working','answer','clarity'].reduce((n,k)=>n+Number(f.get(k)),0)/20,max=Number(f.get('max'));if(attempt){attempt.selfScore=ratio*max;attempt.selfMax=max;save();toast(`Self-assessed: ${(ratio*max).toFixed(1)} / ${max}`)}modal.close();render()}}
function formula(){if(state.session?.mode==='exam'&&!state.session.finished){toast('Formula reference is disabled during exam mode.');return}if(currentQ().subject==='thermodynamics'){showModal('Thermodynamics · quick reference',`<div class="coverage"><p><strong>Energy and processes</strong><br>Closed system: ΔU = Q − W. Boundary work: W = ∫p dV. Ideal gas: pv = RT; cp − cv = R; γ = cp/cv.<br>Polytropic work: (p₂V₂ − p₁V₁)/(1−n), n ≠ 1. Isothermal ideal-gas work: mRT ln(V₂/V₁). Reversible adiabatic: Tv^(γ−1) = constant.</p><br><p><strong>Steady flow</strong><br>q − w = h₂ − h₁ + (V₂² − V₁²)/2000 + g(z₂−z₁)/1000 in kJ/kg. Pump work input ≈ vΔp with p in kPa.<br>Filling/emptying tanks require an unsteady mass and energy balance; inlet energy is enthalpy.</p><br><p><strong>Second law and exergy</strong><br>ηCarnot = 1 − TL/TH. COPR = TL/(TH−TL); COPHP = COPR+1.<br>Ideal-gas Δs = cp ln(T₂/T₁) − R ln(p₂/p₁) = cv ln(T₂/T₁) + R ln(v₂/v₁). Sgen ≥ 0; exergy destruction = T₀ Sgen.<br>Flow exergy = (h−h₀) − T₀(s−s₀) + V²/2000 + gz/1000.</p><br><p><strong>Properties and relations</strong><br>Saturated mixture: y = yf + x(y g−yf), for y = v, u, h or s. Quality x is defined only inside the two-phase region.<br>du = T ds − p dv; dh = T ds + v dp. Maxwell: (∂s/∂v)T = (∂p/∂T)v; (∂s/∂p)T = −(∂v/∂T)p. μJT = [T(∂v/∂T)p−v]/cp.</p><br><p><strong>Cycles and compressors</strong><br>Otto η = 1−r^(1−γ). Diesel η = 1−(rc^γ−1)/[γr^(γ−1)(rc−1)]. Brayton η = 1−rp^((1−γ)/γ).<br>Rankine η = (wt−wp)/qin; steam rate = 3600/wnet. Compressor work input = nRT₁[rp^((n−1)/n)−1]/(n−1); ideal intercooling uses equal stage pressure ratios. ηv = 1+C−C rp^(1/n).</p><br><p><strong>Refrigeration and moist air</strong><br>Vapour compression: COP = (h₁−h₄)/(h₂−h₁), h₄=h₃ for throttling. 1 TR ≈ 3.517 kW.<br>Humidity ratio ω = 0.622 pv/(p−pv); RH = pv/psat(T). Moist-air h ≈ 1.005t+ω(2500+1.88t) kJ/kg dry air.</p><br><p><strong>Compressible flow</strong><br>a=√(γRT), M=V/a; T₀/T=1+(γ−1)M²/2; p₀/p=(T₀/T)^(γ/(γ−1)). Critical p/p₀=[2/(γ+1)]^(γ/(γ−1)). Use absolute temperatures and pressures, consistent mass bases and supplied property tables. All ideal-cycle formulas require their stated assumptions.</p></div>`);return}if(currentQ().subject==='power-plant'){showModal('Power Plant Engineering · quick reference',`<div class="coverage"><p><strong>Steam and steady flow</strong><br>h = hf + xhfg for a saturated mixture · q − w = h₂ − h₁ + (V₂² − V₁²)/2000 + g(z₂ − z₁)/1000, with energy in kJ/kg.</p><br><p><strong>Rankine cycle</strong><br>wt = h₃ − h₄ · wp ≈ vf(p₂ − p₁), using kPa · η = (wt − wp)/(h₃ − h₂) · Steam rate = 3600/wnet in kg/kWh.<br>For an ideal open feedwater heater: y = (hout − hpump)/(hbleed − hpump). Label every extraction stream before using a balance.</p><br><p><strong>Nozzles</strong><br>For an ideal gas: a = √(γRT) · M = V/a · T₀/T = 1 + (γ−1)M²/2 · p₀/p = (T₀/T)^(γ/(γ−1)).<br>Critical p/p₀ = [2/(γ+1)]^(γ/(γ−1)); dA/A = (M²−1)dV/V for isentropic quasi-one-dimensional flow.<br>Adiabatic nozzle: V₂² = V₁² + 2000(h₁−h₂). Include heat loss per unit mass, not total heat-loss rate.</p><br><p><strong>Turbines and compressors</strong><br>Euler stage work = u(Vw₁−Vw₂) · ηt = (h₁−h₂)/(h₁−h₂s) · ηc = (h₂s−h₁)/(h₂−h₁).<br>Polytropic compressor work = nRT₁[(p₂/p₁)^((n−1)/n)−1]/(n−1). Ideal intercooling gives equal stage pressure ratios. Clearance ηv = 1 + C − C rp^(1/n).</p><br><p><strong>Gas plants, boilers and condensers</strong><br>Ideal Brayton η = 1 − rp^((1−γ)/γ) · Optimum rp for maximum net work = (Tmax/Tmin)^(γ/[2(γ−1)]).<br>Boiler η = ṁsteam(hsteam−hfeed)/(ṁfuel × calorific value) · Equivalent evaporation = heat added / 2257 kJ/kg.<br>Condenser balance: ṁsteam(hin−hout) = ṁwater cp ΔTwater.</p><br><p><strong>Renewables and plant economics</strong><br>Wind power = ½ρAV³Cp; ideal Betz Cp ≤ 16/27 · Hydro output = ηρgQH.<br>Load factor = average load / maximum demand · Capacity factor = average load / installed capacity · Simple payback = initial investment / annual net saving.<br>Use absolute pressures and temperatures, consistent units and the supplied property tables. These formulas assume the stated ideal models.</p></div>`);return}if(currentQ().subject==='heat-transfer'){showModal('Heat Transfer · quick reference',`<div class="coverage"><p><strong>Fundamentals</strong><br>q = −kA dT/dx · α = k/(ρcp) · Q = ṁcpΔT · Use a temperature difference in K or °C consistently.</p><br><p><strong>Thermal resistance</strong><br>Plane: R = L/(kA) · Cylinder: R = ln(ro/ri)/(2πkL) · Sphere: R = (1/ri−1/ro)/(4πk) · Convection: R = 1/(hA)<br>Series resistances add; parallel branches share the same temperature difference.</p><br><p><strong>Heat generation and insulation</strong><br>Uniform generation: centre−surface ΔT = gL²/(2k) for a plane half-thickness L, gr²/(4k) for a cylinder, gr²/(6k) for a sphere.<br>Critical outer radius: k/h (cylinder), 2k/h (sphere); below it, added insulation may increase heat loss.</p><br><p><strong>Uniform fins</strong><br>m = √(hP/kAc) · Insulated tip: Qf = √(hPkAc)θb tanh(mL) · ηf = tanh(mL)/(mL)<br>Effectiveness = Qf/(hAcθb); efficiency = Qf/(hAfθb). These are different quantities.</p><br><p><strong>Transient conduction</strong><br>Lc = V/A · Bi = hLc/k · Fo = αt/L²<br>Lumped approximation: Bi ≲ 0.1; θ/θi = exp[−hAt/(ρVcp)]. Check the length convention for each Fourier-number solution.</p><br><p><strong>Convection</strong><br>Nu = hL/kfluid · Re = ρVL/μ · Pr = ν/α · Gr = gβΔTL³/ν² · Ra = GrPr<br>Use correlations only within their geometry, regime, boundary condition and stated validity ranges.</p><br><p><strong>Radiation</strong><br>Eb = σT⁴ · σ = 5.6704×10⁻⁸ W/(m²K⁴) · J = εEb + (1−ε)G for an opaque grey surface<br>ΣjFij = 1 · AiFij = AjFji · Use absolute temperatures in K.<br>Two large diffuse grey plates: q/A = σ(T1⁴−T2⁴)/(1/ε1+1/ε2−1).</p><br><p><strong>Heat exchangers</strong><br>C = ṁcp · Cr = Cmin/Cmax · NTU = UA/Cmin · ε = Q/[Cmin(Th,in−Tc,in)]<br>LMTD = (ΔT1−ΔT2)/ln(ΔT1/ΔT2); its equal-difference limit is ΔT.<br>Parallel: ε = [1−exp(−NTU(1+Cr))]/(1+Cr)<br>Counterflow: ε = [1−exp(−NTU(1−Cr))]/[1−Cr exp(−NTU(1−Cr))]; for Cr = 1, ε = NTU/(1+NTU).<br>When Cr = 0: ε = 1−exp(−NTU). Use the correct terminal temperatures and correction factor.</p><br><p><strong>Boiling and condensation</strong><br>Q = hA(Tsurface−Tsat) · Phase-change balance: Q = ṁhfg<br>Film/dropwise condensation and boiling regimes require different correlations; critical heat flux is a regime limit.</p></div>`);return}if(currentQ().subject==='fluid-mechanics'){showModal('Fluid Mechanics · quick reference',`<div class="coverage"><p><strong>Properties & shear</strong><br>ν = μ/ρ · τ = μ du/dy for a Newtonian fluid · Re = ρVD/μ</p><br><p><strong>Hydrostatics & buoyancy</strong><br>p − p₀ = ρgh · F = ρgA h̄ for a submerged plane · Buoyant force = ρg × displaced volume</p><br><p><strong>Continuity</strong><br>ṁ = ρAV · For steady incompressible flow: A₁V₁ = A₂V₂</p><br><p><strong>Bernoulli & energy</strong><br>p₁/(ρg) + α₁V₁²/(2g) + z₁ + hₚ = p₂/(ρg) + α₂V₂²/(2g) + z₂ + hₜ + hL<br>Ideal Bernoulli assumes steady, incompressible, inviscid flow along a streamline.</p><br><p><strong>Momentum</strong><br>ΣF = Σout ṁV − Σin ṁV for a steady control volume; use vector components.</p><br><p><strong>Pipe losses</strong><br>hL = fD (L/D)V²/(2g) + ΣK V²/(2g) · Darcy fD = 64/Re for fully developed laminar flow in a circular pipe.</p><br><p><strong>Laminar circular pipe</strong><br>Q = πD⁴Δp/(128μL) · Vmax = 2Vmean for fully developed Newtonian flow.</p><br><p><strong>Similarity & external flow</strong><br>Fr = V/√(gL) · We = ρV²L/σ · Ma = V/a · CD = FD/(½ρV²A)</p><br><p><strong>Pumps & turbines</strong><br>Hydraulic power = ρgQH · Pump input = ρgQH/η · Turbine output = ηρgQH</p><br><p>Check fluid properties, assumptions, reference pressure, friction-factor convention, units and sign conventions for each problem.</p></div>`);return}if(currentQ().subject!=='som'){toast('A formula reference has not been added for this subject.');return}showModal('Quick formula reference',`<div class="coverage"><p><strong>Elasticity</strong><br>σ = P/A · ε = δ/L · E = 2G(1+ν) = 3K(1−2ν)</p><br><p><strong>Axial & thermal</strong><br>δ = PL/AE · εₜ = αΔT · Fully restrained σ = EαΔT</p><br><p><strong>Beam bending</strong><br>σ = My/I · τ = VQ/It · EI vʺ = M(x)</p><br><p><strong>Circular shaft torsion</strong><br>τ = Tr/J · θ = TL/GJ · J = πd⁴/32 (solid)</p><br><p><strong>Plane stress</strong><br>σ₁,₂ = (σₓ+σᵧ)/2 ± √[((σₓ−σᵧ)/2)² + τₓᵧ²]</p><br><p><strong>Euler buckling</strong><br>Pcr = π²EI/(KL)² · applies to slender elastic columns</p><br><p><strong>Thin closed cylinder</strong><br>σhoop = pd/2t · σlong = pd/4t</p><br><p>Check assumptions, units, geometry and sign conventions for each problem.</p></div>`)}
function exportData(){const blob=new Blob([JSON.stringify({format:'pyq-lab-backup',version:1,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`pyq-nexus-progress-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function importData(file){if(!file)return;if(file.size>15000000){toast('Backup is too large (15 MB limit).');return}file.text().then(text=>{try{const data=JSON.parse(text),s=data.state;if(!['som-lab-backup','pyq-lab-backup'].includes(data.format)||data.version!==1||!s||!Array.isArray(s.attempts)||['answers','flags','bookmarks','notes','overrides','drawings'].some(k=>!s[k]||typeof s[k]!=='object'||Array.isArray(s[k])))throw Error();if(s.attempts.some(a=>!LIBRARY.original.has(a.id)||!Number.isFinite(a.at)||(a.score!==null&&!Number.isFinite(a.score))||(a.selfScore!==undefined&&!Number.isFinite(a.selfScore))||!['correct','wrong','skipped','ungraded','manual'].includes(a.status)))throw Error();if(s.session&&(!Array.isArray(s.session.ids)||s.session.ids.some(id=>!LIBRARY.original.has(id))||!Number.isInteger(s.session.index)||s.session.index<0||s.session.index>=s.session.ids.length||!s.session.answers||!s.session.times))throw Error();for(const [id,o] of Object.entries(s.overrides)){if(!LIBRARY.original.has(id)||!['MCQ','MSQ','NAT','TEXT','WRITTEN'].includes(o.type)||!Number.isFinite(o.marks)||o.marks<=0)throw Error();if(o.key&&o.type==='TEXT'&&(!Array.isArray(o.key.acceptedText)||!o.key.acceptedText.length||o.key.acceptedText.some(v=>typeof v!=='string'||!v.trim()||v.length>500)))throw Error();if(o.key&&o.type==='NAT'&&(!Number.isFinite(o.key.min)||!Number.isFinite(o.key.max)||o.key.min>o.key.max))throw Error();if(o.key&&['MCQ','MSQ'].includes(o.type)&&(!Array.isArray(o.key.options)||!o.key.options.length||o.key.options.some(v=>!['A','B','C','D'].includes(v))))throw Error()}if(s.subject&&s.subject!=='all'&&!subjectInfo(s.subject))throw Error();if(s.planner&&(!Array.isArray(s.planner)||s.planner.length>5000||s.planner.some(t=>!t||typeof t.id!=='string'||typeof t.title!=='string'||t.title.length>100||!subjectInfo(t.subject)||typeof t.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(t.date)||!Number.isFinite(t.minutes)||t.minutes<5||t.minutes>480||typeof t.done!=='boolean')))throw Error();showModal('Restore this backup?',`<p>${s.attempts.length} attempts, exported ${esc(data.exportedAt)}. This replaces the progress currently saved in this browser.</p><div class="form-actions"><button id="confirm-import" class="primary">Restore backup</button><button data-close>Cancel</button></div>`);$('#confirm-import').onclick=()=>{state=PYQDedup.migrate({...s,subject:s.subject||'all',planner:s.planner||[],preferences:PYQInsights.preferences(s.preferences),learningPreferences:PYQLearning.preferences(s.learningPreferences)},LIBRARY);revealed.clear();save();modal.close();navigate('dashboard');toast('Backup restored')}}catch{toast('This is not a valid PYQ Nexus or SOM Lab backup.')}})}
function bindLocal(){if($('#search'))$('#search').oninput=e=>{filter.search=e.target.value;page=0;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};for(const k of ['type','chapter','topic','year','status','source'])if($('#filter-'+k))$('#filter-'+k).onchange=e=>{filter[k]=e.target.value;if(k==='chapter')filter.topic='all';if(k==='topic'&&filter.topic!=='all'){const q=BANK.find(q=>q.topicId===filter.topic);if(q)filter.chapter=q.chapterId}page=0;render()};if($('#nat-input'))$('#nat-input').oninput=e=>answer(e.target.value,false);if($('#text-input'))$('#text-input').oninput=e=>answer(e.target.value,false);if($('#written-input'))$('#written-input').oninput=e=>answer(e.target.value,false);if($('#notes'))$('#notes').oninput=e=>{state.notes[currentQ().id]=e.target.value;save()};if($('#backup-file'))$('#backup-file').onchange=e=>importData(e.target.files[0]);if($('#mock-form'))$('#mock-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),written=f.get('exam').includes('mains');const subjects=f.getAll('subjects');if(!subjects.length){toast('Select at least one available subject.');return}let qs=BANK.map(q=>qData(q.id)).filter(q=>subjects.includes(q.subject)&&q.exam===f.get('exam')&&(f.get('type')==='all'||q.type===f.get('type'))&&(f.get('coverage')==='all'||written||q.key)&&q.type!=='UNCLASSIFIED');for(let i=qs.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[qs[i],qs[j]]=[qs[j],qs[i]]}if(f.get('selection')==='adaptive'){const weight=q=>(status(q)==='wrong'?6:0)+(state.flags[q.id]?4:0)+(status(q)==='new'?2:0);qs.sort((a,b)=>weight(b)-weight(a))}if(f.get('selection')==='weak')qs.sort((a,b)=>(status(b)==='wrong')-(status(a)==='wrong'));if(f.get('selection')==='new')qs.sort((a,b)=>(status(b)==='new')-(status(a)==='new'));const count=Number(f.get('count'));if(qs.length<count){toast(`Only ${qs.length} questions match. Reduce the set size or broaden the selection.`);return}startSession(qs.slice(0,count).map(q=>q.id),'exam',Number(f.get('minutes')))};}
function answer(v,rerender=true){const s=state.session,q=currentQ();if(s.finished||s.mode==='practice'&&s.submitted[q.id])return;s.answers[q.id]=v;save();if(rerender)render()}
function jump(i){const s=state.session;s.index=Math.max(0,Math.min(s.ids.length-1,i));s.visited[s.ids[s.index]]=true;save();render()}
const actions={'recheck-answers':recheckSavedAnswers,quick:startSmartPractice,review:()=>navigate('review'),'practice-filter':()=>{const rows=filterQuestions();startSession(rows.length>200?PYQCurriculum.next(rows,state.attempts,200):rows.map(q=>q.id))}, 'page-prev':()=>{page--;render()},'page-next':()=>{page++;render()},bookmark:()=>{const id=currentQ().id;state.bookmarks[id]=!state.bookmarks[id];save();render()},zoom:()=>$('#question-sheet').classList.toggle('zoom'),flag:()=>{const id=currentQ().id;state.flags[id]=!state.flags[id];save();render()},'clear-answer':()=>answer(''),check:checkAnswer,'show-answer':()=>{if(state.session.mode==='practice'){revealed.add(currentQ().id);render()}},issues:()=>{resetFilters();filter.status='issues';state.subject='all';save();navigate('bank')},next:()=>state.session.index===state.session.ids.length-1?finish():jump(state.session.index+1),finish:()=>finish(),calculator,scratch,formula,'edit-key':editKey,'self-review':selfReview,'retry-mistakes':()=>startSession(state.session.ids.filter(id=>C.grade(qData(id),state.session.answers[id]).status==='wrong')),'review-all':()=>startSession(revisionRows().ids.slice(0,learnPrefs().dueLimit)),export:exportData,import:()=>$('#backup-file').click(),theme:()=>{state.theme=state.theme==='dark'?'light':'dark';save();render()},pending:()=>{filter.status='missing';filter.exam='all';filter.type='all';filter.chapter='all';filter.topic='all';filter.year='all';filter.source='all';filter.search='';page=0;navigate('bank')}};
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.hasAttribute('data-close'))modal.close();if(b.dataset.view)navigate(b.dataset.view);if(b.dataset.track||b.dataset.filterTrack){filter={exam:b.dataset.track||b.dataset.filterTrack,type:'all',chapter:b.dataset.filterTrack?filter.chapter:'all',topic:b.dataset.filterTrack?filter.topic:'all',year:'all',status:'all',source:'all',search:''};page=0;navigate('bank')}if(b.dataset.chapter){filter={exam:'all',type:'all',year:'all',status:'all',source:'all',search:'',chapter:b.dataset.chapter,topic:'all'};page=0;navigate('bank')}if(b.dataset.open)startSession([b.dataset.open]);if(b.dataset.action)actions[b.dataset.action]?.();if(b.dataset.jump!==undefined)jump(Number(b.dataset.jump));if(b.dataset.option){const q=currentQ(),a=state.session.answers[q.id]||[];answer(q.type==='MSQ'?(a.includes(b.dataset.option)?a.filter(x=>x!==b.dataset.option):[...a,b.dataset.option]):b.dataset.option)}if(b.dataset.keypad){const input=$('#nat-input');let v=input.value,k=b.dataset.keypad;if(k==='C')v='';else if(k==='⌫')v=v.slice(0,-1);else if(k==='−')v=v.startsWith('-')?v.slice(1):'-'+v;else if(k!=='.'||!v.includes('.'))v+=k;input.value=v;answer(v,false)}if(b.dataset.calc){const k=b.dataset.calc,input=$('#calc-input');if(k==='=')calcResult();else if(k==='C'){input.value='';$('#calc-output').textContent=''}else input.value+=k}});
$('#theme-toggle').onclick=actions.theme;$('#help-btn').onclick=()=>showModal('A little less clicking.',`<div class="coverage"><p><strong>← / →</strong> Previous / next question</p><p><strong>1, 2, 3, 4</strong> Select A, B, C, D</p><p><strong>R</strong> Mark for review</p><p><strong>Escape</strong> Close a dialog</p><br><p>Shortcuts are paused while typing. Responses and notes save automatically on this device. Export backups regularly from Data & settings.</p></div>`);
document.addEventListener('keydown',e=>{if(modal.open||view!=='practice'||state.session?.finished||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.key==='ArrowRight')jump(state.session.index+1);if(e.key==='ArrowLeft')jump(state.session.index-1);if(e.key.toLowerCase()==='r')actions.flag();if(['1','2','3','4'].includes(e.key))$(`[data-option="${'ABCD'[Number(e.key)-1]}"]`)?.click()});
setInterval(()=>{const now=Date.now(),delta=Math.min((now-tickAt)/1000,3);tickAt=now;const s=state.session;if(!s||s.finished)return;if(view==='practice'&&document.visibilityState==='visible')s.times[s.ids[s.index]]=(s.times[s.ids[s.index]]||0)+delta;if(s.mode==='exam'&&now>=s.deadline){if(modal.open)modal.close();finish(true);toast('Time is up. Your test has been submitted.');return}if(s.mode==='exam'&&$('#session-clock'))$('#session-clock').textContent=fmt((s.deadline-now)/1000);if(Math.floor(now/1000)%5===0)save()},1000);
save();window.addEventListener('beforeunload',save);if(state.session&&!state.session.finished&&state.session.mode==='exam'&&Date.now()>=state.session.deadline)finish(true);else render();
